#!/usr/bin/env python3
import socket, struct, sys

def enc_name(n):
    out = b''
    n = n.rstrip('.')
    if n:
        for lab in n.split('.'):
            out += bytes([len(lab)]) + lab.encode()
    return out + b'\x00'

def dec_name(data, off):
    labs = []
    while True:
        l = data[off]
        if l == 0:
            off += 1
            break
        if l & 0xC0 == 0xC0:
            ptr = struct.unpack('!H', data[off:off+2])[0] & 0x3FFF
            sub, _ = dec_name(data, ptr)
            labs.append(sub)
            off += 2
            break
        off += 1
        labs.append(data[off:off+l].decode())
        off += l
    return '.'.join(labs), off

A, NS, CNAME, SOA, PTR, MX, TXT, AAAA, SRV = 1, 2, 5, 6, 12, 15, 16, 28, 33

def a(ip):  return (A, socket.inet_aton(ip))
def aaaa(ip): return (AAAA, socket.inet_pton(socket.AF_INET6, ip))
def cname(n): return (CNAME, enc_name(n))
def txt(*ss):
    b = b''
    for s in ss:
        e = s.encode()
        b += bytes([len(e)]) + e
    return (TXT, b)
def srv(prio, weight, port, target):
    return (SRV, struct.pack('!HHH', prio, weight, port) + enc_name(target))

ZONE = {
  'one.example.test':   [a('1.2.3.4')],
  'multi.example.test': [a('10.0.0.1'), a('10.0.0.2'), a('10.0.0.3')],
  'both.example.test':  [a('9.9.9.9'), aaaa('2001:db8::1')],
  'v6only.example.test':[aaaa('2001:db8::99')],
  'cname.example.test': [cname('target.example.test.'), a('5.6.7.8')],
  'target.example.test':[a('5.6.7.8')],
  'txt.example.test':   [txt('v=spf1 -all'), txt('hello world', 'second chunk')],
  '_sip._udp.example.test': [srv(10, 1, 5060, 'sip1.example.test.'),
                             srv(20, 5, 5061, 'sip2.example.test.')],
  'empty.example.test': [],
}

def handle(data):
    tid = data[:2]
    qname, off = dec_name(data, 12)
    qtype, qclass = struct.unpack('!HH', data[off:off+4])
    off += 4
    q = data[12:off]
    key = qname.lower().rstrip('.')
    recs = ZONE.get(key)
    if recs is None:
        # NXDOMAIN
        hdr = tid + struct.pack('!HHHHH', 0x8583, 1, 0, 0, 0)
        return hdr + q
    ans = b''
    n = 0
    for (t, rd) in recs:
        if t == qtype or (qtype == 255):
            ans += enc_name(qname) + struct.pack('!HHIH', t, 1, 60, len(rd)) + rd
            n += 1
    if n == 0:
        for (t, rd) in recs:
            if t == CNAME:
                ans += enc_name(qname) + struct.pack('!HHIH', t, 1, 60, len(rd)) + rd
                n += 1
    hdr = tid + struct.pack('!HHHHH', 0x8580, 1, n, 0, 0)
    return hdr + q + ans

s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
s.bind(('127.0.0.1', 53))
t = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
t.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
t.bind(('127.0.0.1', 53))
t.listen(5)
import threading
def tcp():
    while True:
        c, _ = t.accept()
        try:
            ln = struct.unpack('!H', c.recv(2))[0]
            d = c.recv(ln)
            r = handle(d)
            c.sendall(struct.pack('!H', len(r)) + r)
        except Exception as e:
            pass
        c.close()
threading.Thread(target=tcp, daemon=True).start()
sys.stderr.write("dns up\n"); sys.stderr.flush()
while True:
    d, addr = s.recvfrom(4096)
    try:
        s.sendto(handle(d), addr)
    except Exception as e:
        sys.stderr.write("err %s\n" % e)

